import {defineTrace} from './trace-model.js';

export const overloadResolutionTrace = defineTrace({
  version: 1,
  id: 'overload-resolution-generic-fallback',
  title: 'How Pyright selects an overload',
  sourceRef: {
    repository: 'bschnurr/pyright',
    branch: 'typeEval-explained',
  },
  example: [
    'from typing import overload, TypeVar',
    '',
    'T = TypeVar("T")',
    '',
    '@overload',
    'def transform(value: int) -> str: ...',
    '@overload',
    'def transform(value: T) -> list[T]: ...',
    '',
    'result = transform(1)',
  ].join('\n'),
  focus: {line: 10, expression: 'transform(1)'},
  events: [
    {
      id: 'call-enter',
      kind: 'enter',
      module: 'expressionEvaluation',
      operation: 'evaluate call expression',
      node: 'CallNode transform(1)',
      caption: 'The evaluator starts with the CallNode and asks for the type of its callee.',
    },
    {
      id: 'callee-dispatch',
      kind: 'dispatch',
      module: 'evaluatorCore',
      operation: 'getTypeOfExpression',
      from: 'CallNode',
      to: 'NameNode transform',
      caption: 'Expression dispatch evaluates transform and obtains an overloaded function type.',
    },
    {
      id: 'overload-one',
      kind: 'candidate',
      module: 'expressionEvaluation',
      candidate: 1,
      signature: '(value: int) -> str',
      status: 'testing',
      caption: 'Candidate one is considered in declaration order.',
    },
    {
      id: 'overload-one-assign',
      kind: 'compatibility',
      module: 'assignFunctions',
      candidate: 1,
      sourceType: 'Literal[1]',
      destinationType: 'int',
      compatible: true,
      caption: 'Literal[1] is compatible with int, so the first candidate survives.',
    },
    {
      id: 'overload-one-accepted',
      kind: 'candidate',
      module: 'expressionEvaluation',
      candidate: 1,
      signature: '(value: int) -> str',
      status: 'accepted',
      caption: 'The matching overload determines a str return type.',
    },
    {
      id: 'call-cache',
      kind: 'cache',
      module: 'evaluatorCore',
      operation: 'write',
      cache: 'node type cache',
      key: 'CallNode transform(1)',
      type: 'str',
      speculative: false,
      caption: 'The completed TypeResult is cached for this parse node.',
    },
    {
      id: 'call-result',
      kind: 'result',
      module: 'expressionEvaluation',
      type: 'str',
      incomplete: false,
      caption: 'The call expression evaluates to str.',
    },
    {
      id: 'call-leave',
      kind: 'leave',
      module: 'expressionEvaluation',
      operation: 'evaluate call expression',
      caption: 'Evaluation returns to the containing assignment.',
    },
  ],
});

export const genericOverloadTrace = defineTrace({
  version: 1,
  id: 'overload-resolution-typevar',
  title: 'How a generic overload solves a TypeVar',
  sourceRef: {
    repository: 'bschnurr/pyright',
    branch: 'typeEval-explained',
  },
  example: overloadResolutionTrace.example.replace('transform(1)', 'transform("hello")'),
  focus: {line: 10, expression: 'transform("hello")'},
  events: [
    {
      id: 'generic-enter',
      kind: 'enter',
      module: 'expressionEvaluation',
      operation: 'evaluate call expression',
      node: 'CallNode transform("hello")',
      caption: 'The call resolves to the same overloaded function.',
    },
    {
      id: 'specific-test',
      kind: 'candidate',
      module: 'expressionEvaluation',
      candidate: 1,
      signature: '(value: int) -> str',
      status: 'testing',
      caption: 'The specific overload is tested first.',
    },
    {
      id: 'specific-reject',
      kind: 'compatibility',
      module: 'assignFunctions',
      candidate: 1,
      sourceType: 'Literal["hello"]',
      destinationType: 'int',
      compatible: false,
      caption: 'str is not assignable to int.',
    },
    {
      id: 'specific-rejected',
      kind: 'candidate',
      module: 'expressionEvaluation',
      candidate: 1,
      signature: '(value: int) -> str',
      status: 'rejected',
      reason: 'Argument of type str cannot be assigned to parameter of type int.',
      caption: 'The failure is retained as diagnostic evidence while matching continues.',
    },
    {
      id: 'generic-test',
      kind: 'candidate',
      module: 'expressionEvaluation',
      candidate: 2,
      signature: '(value: T) -> list[T]',
      status: 'testing',
      caption: 'The generic fallback is tested next.',
    },
    {
      id: 'generic-constraint',
      kind: 'constraint',
      module: 'typeVarHandling',
      typeVar: 'T',
      lowerBound: 'str',
      solution: 'str',
      caption: 'The argument contributes a constraint and T is solved as str.',
    },
    {
      id: 'generic-compatible',
      kind: 'compatibility',
      module: 'assignFunctions',
      candidate: 2,
      sourceType: 'Literal["hello"]',
      destinationType: 'T → str',
      compatible: true,
      caption: 'After specialization, the argument is compatible.',
    },
    {
      id: 'generic-accepted',
      kind: 'candidate',
      module: 'expressionEvaluation',
      candidate: 2,
      signature: '(value: str) -> list[str]',
      status: 'accepted',
      caption: 'The generic overload is selected with its solved type argument.',
    },
    {
      id: 'generic-result',
      kind: 'result',
      module: 'expressionEvaluation',
      type: 'list[str]',
      incomplete: false,
      caption: 'The specialized return type is list[str].',
    },
    {
      id: 'generic-leave',
      kind: 'leave',
      module: 'expressionEvaluation',
      operation: 'evaluate call expression',
      caption: 'Evaluation returns to the containing assignment.',
    },
  ],
});

export const scenarios = Object.freeze([
  overloadResolutionTrace,
  genericOverloadTrace,
]);
